import{_ as o,l as s,o as e,c as i,v as t,p as l,x as n,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"跳跃与新闻事件","description":"","frontmatter":{"title":"跳跃与新闻事件","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/jumps-news.md","filePath":"quant/jumps-news.md","lastUpdated":1789023840000}'),h={name:"quant/jumps-news.md"};function m(A,a,B,c,u,_){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="跳跃与新闻事件" tabindex="-1">跳跃与新闻事件 <a class="header-anchor" href="#跳跃与新闻事件" aria-label="Permalink to &quot;跳跃与新闻事件&quot;">​</a></h1><div class="epigraph"><p>宏观公告时刻，价格可以在连续波动之外再加一跳；检验拒绝连续路径之后，还要把跳对到时钟上的新闻，而不是把所有显著 $Z_J$ 都叫做消息。</p><footer>—— Andersen, Bollerslev, Diebold and Vega, Micro Effects of Macro Announcements: Real-Time Price Discovery in Foreign Exchange, American Economic Review, 2003；跳的定位见 Lee and Mykland, Review of Financial Studies, 2008</footer></div><p><a href="/quant/noise-variance-estimate">上一课</a>把签名图的高频上翘留给噪声、把平台抬高留给跳。<a href="/quant/jump-tests">跳跃检验</a> 已给出 BN–S 与 Lee–Mykland。本课缺口：把检出的跳<strong>对齐到新闻时间表</strong>——非农、CPI、FOMC、个股盈余。Andersen、Bollerslev、Diebold 与 Vega 用高频外汇看宏观意外的即时效应；Lee–Mykland 给出格点定位。对象是「跳是否在公告窗」，不是再推导双幂次。下一课点过程给公告之间的等待时间建模，强度可以在新闻时刻抬升。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无条件跳检验回答「当天有没有跳」。新闻研究问：跳是否落在 \\(\\pm\\Delta\\) 的公告窗、意外大小是否解释跳的符号与幅度。问题是多重检验（一年许多公告）、时区、预泄漏、以及连续波动在公告前已经季节性抬高——未除季节会把「忙」当成跳。</p><p>对象分层：（1）宏观对汇率/国债/股指的共同跳；（2）个股特异跳（并购、盈余）。共同跳进入已实现协方差的共跳项；特异跳进入半方差的一侧。先标类型再做定价或对冲。</p><h3 id="窗宽与意外" tabindex="-1">窗宽与意外 <a class="header-anchor" href="#窗宽与意外" aria-label="Permalink to &quot;窗宽与意外&quot;">​</a></h3><p>标准化意外 \\(s_t=(a_t-E[a_t])/\\sigma_a\\)，回归 \\(r_{t,i}=\\gamma s_t 1_{i\\in\\mathrm{窗}}+\\cdots\\)。窗太宽混进无关波动，太窄错过慢消化。外汇里数秒到数分钟；个股盈余可能数十分钟。应预登记窗，并报告泄漏窗 \\(t\\lt 0\\)。</p><p><span class="marginnote">「有新闻的日子 RV 高」可以全是连续 \\(\\sigma\\) 升，BN–S 不拒绝。新闻效应不等于跳效应。应同时报窗内连续波动与跳贡献。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>定位。</strong> Lee–Mykland 局部 \\(\\sigma\\) 标准化 \\(|r_i|\\)，标出格。与官方时间戳对齐（注意发布延迟与交易所时钟，见时钟课）。BN–S 只给日度，不够对到分钟。</p><p><strong>回归。</strong> 窗内收益或已实现跳对意外；标准误按公告聚类（同一宏观日所有资产相关）。这是 <a href="/quant/event-study">事件研究</a> 的高频版，异方差用窗内已实现量标准化。</p><p><strong>共同 vs 特异。</strong> 指数跳而成分未跳：可能是期货–现货同步问题。成分都跳：共跳。HY 或刷新格上的共跳检验（Jacod–Todorov 一类）比「大家都显著」的 Bonferroni 更对口，但实现重。工程上先看指数窗，再抽样成分。</p><h3 id="与半方差、对冲" tabindex="-1">与半方差、对冲 <a class="header-anchor" href="#与半方差、对冲" aria-label="Permalink to &quot;与半方差、对冲&quot;">​</a></h3><p>负宏观意外 → \\(RS^-\\) 与负跳。对冲若假设连续路径，新闻窗应切换限额或期权保护，而不是把 \\(Z_J\\) 当反向信号。检出是事后分解；可交易的是预先知道的日历（公告时刻已知、意外未知）。日历本身可进季节与强度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公告把信息集在离散时刻更新，半鞅允许不连续。若做市在窗内用宽价差吸收，观测到的 \\(Y\\) 跳含噪声加宽；应中点或预平均再测跳，否则把价差拉宽当成跳。机制：真信息跳持久，价差跳反向。事后几分钟是否回吐是诊断。</p><p>Andersen 等强调价格发现速度：汇率对宏观的调整可以在一次印记里完成大部分。这与日频事件研究的「几天 CAR」不同——对象已经是秒到分钟。日频 CAR 会把跳与随后的连续波动加总。</p><p><span class="marginnote">多重公告同一分钟（数据扎堆）无法分离哪个数字造成跳。应看官方日历是否重叠，重叠则把窗标为「包」，不要硬归因。</span></p><h3 id="到点过程的交接" tabindex="-1">到点过程的交接 <a class="header-anchor" href="#到点过程的交接" aria-label="Permalink to &quot;到点过程的交接&quot;">​</a></h3><p>跳与普通成交都是点事件。新闻时刻强度 \\(\\lambda(t)\\) 升，久期变短。下一课 ACD/Hawkes 式点过程给「下一笔何时来」，本课的跳是标值（有方向的幅度）。先标值再点过程，避免把所有密集成交都叫跳。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>假新闻、社交媒体时间戳不可靠。停牌使公告落在空洞，跳出现在复牌第一笔，应对齐复牌而非公告墙钟。A 股业绩预告与正式公告多时点，预登记哪一个 \\(t=0\\)。</p><p>工程：预登记日历与窗；Lee–Mykland + 意外回归；按日聚类。不要把所有 BN–S 显著日讲成新闻日。不要用日收益对意外回归冒充高频发现。下一课：久期与点过程。</p>',24)),(e(),l(p,null,{default:n(()=>[E(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22Lee-Mykland%20%E5%AE%9A%E4%BD%8D%E8%B7%B3%E6%A0%BC%22%5D%20--%3E%20CAL%5B%22%E5%AF%B9%E9%BD%90%E5%85%AC%E5%91%8A%E6%97%B6%E9%92%9F%22%5D%0A%20%20SUR%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E6%84%8F%E5%A4%96%22%5D%20--%3E%20REG%5B%22%E7%AA%97%E5%86%85%E6%94%B6%E7%9B%8A%20%2F%20%E8%B7%B3%E5%B9%85%E5%BA%A6%E5%9B%9E%E5%BD%92%22%5D%0A%20%20CAL%20--%3E%20REG%0A%20%20SEAS%5B%22%E5%85%88%E9%99%A4%E5%AD%A3%E8%8A%82%20%2F%20%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20J%0A%20%20REG%20--%3E%20TYP%5B%22%E5%85%B1%E5%90%8C%E8%B7%B3%20vs%20%E7%89%B9%E5%BC%82%E8%B7%B3%22%5D%0A%20%20TYP%20--%3E%20PP%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%BC%BA%E5%BA%A6%E4%B8%8E%E4%B9%85%E6%9C%9F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跳检验之后须对到新闻时钟；新闻高波动可以是连续 \\(\\sigma\\)，不必是跳。</li><li>Lee–Mykland 给格点，BN–S 给日度；意外回归按公告聚类，窗宽预登记。</li><li>价差拉宽与真信息跳要用中点/回吐诊断分开。</li><li>公告时刻已知、意外未知：日历进强度，幅度仍不可预知。</li><li>出处：Andersen, Bollerslev, Diebold and Vega, <em>AER</em>, 2003 及后续；Lee and Mykland, <em>RFS</em>, 2008；BN–S 跳跃检验见 <a href="/quant/jump-tests">跳跃检验</a>。</li></ul>',2))])}const g=o(h,[["render",m]]);export{q as __pageData,g as default};
